package stirling.software.SPDF.controller.api;

import java.io.IOException;

import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.multipart.MultipartFile;

import io.github.pixee.security.Filenames;
import io.swagger.v3.oas.annotations.Operation;

import lombok.RequiredArgsConstructor;

import stirling.software.SPDF.config.swagger.StandardPdfResponse;
import stirling.software.SPDF.model.api.general.ColoringBookRequest;
import stirling.software.common.annotations.AutoJobPostMapping;
import stirling.software.common.annotations.api.GeneralApi;
import stirling.software.common.enumeration.ResourceWeight;
import stirling.software.common.model.tool.ToolArity;
import stirling.software.common.model.tool.ToolFormat;
import stirling.software.common.model.tool.ToolIO;
import stirling.software.common.service.CustomPDFDocumentFactory;
import stirling.software.common.util.GeneralUtils;
import stirling.software.common.util.PdfUtils;
import stirling.software.common.util.WebResponseUtils;

@GeneralApi
@RequiredArgsConstructor
public class ColoringBookController {

    private final CustomPDFDocumentFactory pdfDocumentFactory;

    /**
     * Returns one A4 portrait PDF in upload/frame order, with a blank back for every image.
     * Invalid inputs fail the entire batch before a response is returned.
     *
     * @throws IllegalArgumentException if the batch is absent or contains missing/empty uploads
     * @throws IOException if any image cannot be decoded or the PDF cannot be saved
     */
    @AutoJobPostMapping(
            value = "/coloring-book",
            consumes = MediaType.MULTIPART_FORM_DATA_VALUE,
            resourceWeight = ResourceWeight.LARGE_WEIGHT)
    @StandardPdfResponse
    @ToolIO(
            accepts = ToolFormat.IMAGE,
            imageIOInput = true,
            produces = ToolFormat.PDF,
            arity = ToolArity.MISO)
    @Operation(
            summary = "Create a coloring book from images",
            description =
                    "Fits ordered images to A4 portrait pages, preserving colors and proportions."
                            + " Every image is followed by a blank page for duplex printing.")
    public ResponseEntity<byte[]> createColoringBook(@ModelAttribute ColoringBookRequest request)
            throws IOException {
        MultipartFile[] files = request.getFileInput();
        byte[] bytes = PdfUtils.createColoringBook(files, pdfDocumentFactory);
        String filename = Filenames.toSimpleFileName(files[0].getOriginalFilename());
        return WebResponseUtils.bytesToWebResponse(
                bytes, GeneralUtils.generateFilename(filename, "_coloring_book.pdf"));
    }
}

