package stirling.software.SPDF.controller.api;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.multipart;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.lang.reflect.Method;
import java.util.List;
import java.util.Map;

import javax.imageio.ImageIO;

import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.graphics.image.PDImageXObject;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.NullAndEmptySource;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.web.method.HandlerMethod;
import org.springframework.web.multipart.MultipartFile;

import io.swagger.v3.oas.models.Operation;

import stirling.software.SPDF.model.api.general.ColoringBookRequest;
import stirling.software.common.annotations.AutoJobPostMapping;
import stirling.software.common.config.swagger.ToolIOOperationCustomizer;
import stirling.software.common.enumeration.ResourceWeight;
import stirling.software.common.model.tool.ToolArity;
import stirling.software.common.model.tool.ToolFormat;
import stirling.software.common.model.tool.ToolIO;
import stirling.software.common.service.CustomPDFDocumentFactory;

class ColoringBookControllerTest {

    private ColoringBookController controller;
    private MockMvc mockMvc;

    @BeforeEach
    void setUp() throws IOException {
        CustomPDFDocumentFactory factory = mock(CustomPDFDocumentFactory.class);
        when(factory.createNewDocument()).thenAnswer(invocation -> new PDDocument());
        controller = new ColoringBookController(factory);
        mockMvc = MockMvcBuilders.standaloneSetup(controller).build();
    }

    @Test
    void multipartBatchProducesOrderedImagesWithBlankBacks() throws Exception {
        MvcResult result =
                mockMvc.perform(
                                multipart("/api/v1/general/coloring-book")
                                        .file(image("zebra.png", Color.RED))
                                        .file(image("apple.png", Color.BLUE)))
                        .andExpect(status().isOk())
                        .andReturn();

        assertThat(result.getResponse().getContentType()).isEqualTo("application/pdf");
        assertThat(result.getResponse().getHeader("Content-Disposition"))
                .contains("attachment", "zebra_coloring_book.pdf");
        try (PDDocument document = Loader.loadPDF(result.getResponse().getContentAsByteArray())) {
            assertThat(document.getNumberOfPages()).isEqualTo(4);
            assertThat(imageColor(document.getPage(0))).isEqualTo(Color.RED.getRGB());
            assertThat(imageColor(document.getPage(2))).isEqualTo(Color.BLUE.getRGB());
            assertThat(document.getPage(1).hasContents()).isFalse();
            assertThat(document.getPage(3).hasContents()).isFalse();
        }
    }

    @Test
    void pathLikeSourceNameProducesSafeAttachmentFilename() throws Exception {
        ColoringBookRequest request = request(image("../../private/art.png", Color.GREEN));

        var response = controller.createColoringBook(request);

        assertThat(response.getHeaders().getContentDisposition().getFilename())
                .isEqualTo("art_coloring_book.pdf");
    }

    @ParameterizedTest
    @NullAndEmptySource
    void rejectsMissingBatchBeforeReadingFirstFilename(MultipartFile[] files) {
        ColoringBookRequest request = new ColoringBookRequest();
        request.setFileInput(files);

        assertThatThrownBy(() -> controller.createColoringBook(request))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("At least one image");
    }

    @Test
    void rejectsEmptyUploadInOtherwiseValidBatch() throws Exception {
        ColoringBookRequest request =
                request(
                        image("good.png", Color.RED),
                        new MockMultipartFile("fileInput", "empty.png", "image/png", new byte[0]));

        assertThatThrownBy(() -> controller.createColoringBook(request))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("empty.png");
    }

    @Test
    void unreadableInputAbortsOtherwiseValidBatchWithSafeInputName() throws Exception {
        ColoringBookRequest request =
                request(
                        image("good.png", Color.RED),
                        new MockMultipartFile(
                                "fileInput", "../../bad.png", "image/png", new byte[] {1, 2, 3}));

        assertThatThrownBy(() -> controller.createColoringBook(request))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("Unable to read image: bad.png")
                .hasMessageNotContaining("../");
    }

    @Test
    void unsupportedInputPropagatesDecodeFailure() {
        ColoringBookRequest request =
                request(
                        new MockMultipartFile(
                                "fileInput", "document.pdf", "application/pdf", "%PDF".getBytes()));

        assertThatThrownBy(() -> controller.createColoringBook(request))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("document.pdf");
    }

    @Test
    void generatedCompatibilityRestrictsBatchToInstalledImageReaders() throws Exception {
        Method method =
                ColoringBookController.class.getMethod(
                        "createColoringBook", ColoringBookRequest.class);
        ToolIO io = method.getAnnotation(ToolIO.class);
        assertThat(io.accepts()).containsExactly(ToolFormat.IMAGE);
        assertThat(io.imageIOInput()).isTrue();
        assertThat(io.produces()).isEqualTo(ToolFormat.PDF);
        assertThat(io.arity()).isEqualTo(ToolArity.MISO);
        assertThat(method.getAnnotation(AutoJobPostMapping.class).resourceWeight())
                .isEqualTo(ResourceWeight.LARGE_WEIGHT);

        Operation operation =
                new ToolIOOperationCustomizer()
                        .customize(new Operation(), new HandlerMethod(controller, method));
        Map<?, ?> declaration = (Map<?, ?>) operation.getExtensions().get("x-stirling-io");
        assertThat(declaration.get("arity")).isEqualTo("MISO");
        List<?> extensions = (List<?>) declaration.get("inputExtensions");
        assertThat(extensions.containsAll(List.of("png", "jpg", "jpeg", "tiff", "webp"))).isTrue();
        assertThat(extensions.contains("pdf")).isFalse();
    }

    private static ColoringBookRequest request(MultipartFile... files) {
        ColoringBookRequest request = new ColoringBookRequest();
        request.setFileInput(files);
        return request;
    }

    private static MockMultipartFile image(String name, Color color) throws IOException {
        BufferedImage image = new BufferedImage(10, 20, BufferedImage.TYPE_INT_RGB);
        for (int x = 0; x < image.getWidth(); x++) {
            for (int y = 0; y < image.getHeight(); y++) {
                image.setRGB(x, y, color.getRGB());
            }
        }
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        ImageIO.write(image, "png", output);
        return new MockMultipartFile("fileInput", name, "image/png", output.toByteArray());
    }

    private static int imageColor(PDPage page) throws IOException {
        var name = page.getResources().getXObjectNames().iterator().next();
        PDImageXObject image = (PDImageXObject) page.getResources().getXObject(name);
        return image.getImage().getRGB(0, 0);
    }
}
